export type ProjectsListData = {
    body?: never;
    path?: never;
    query?: {
        /**
         * Page number (1-indexed, default: 1)
         */
        page?: number;
        /**
         * Items per page (default: 20, max: 100)
         */
        per_page?: number;
        /**
         * Sort order direction (default: desc = newest first)
         */
        order?: SortOrder;
        /**
         * Window for the per-project stats on each row (e.g. `24h`, `7d`).
         *
         * Omitted means the caller does not want stats at all, and the extra
         * aggregate queries are skipped entirely — this is what keeps the plain
         * `GET /api/projects` that SDK tooling and the project picker use as
         * cheap as it was before the list table grew a sparkline. Sentry's own
         * projects endpoint gates its `stats` field on `?statsPeriod=` the same
         * way.
         */
        stats_period?: string | null;
    };
    url: '/api/projects';
};

export type ProjectsListErrors = {
    /**
     * Unauthorized
     */
    401: ErrorResponse;
};

export type ProjectsListError = ProjectsListErrors[keyof ProjectsListErrors];

export type ProjectsListResponses = {
    /**
     * Offset-based paginated response wrapper
     */
    200: {
        items: Array<{
            created_at: string;
            digested_event_count: number;
            dsn: string;
            id: number;
            name: string;
            platform: string | null;
            rate_limit_per_hour: number | null;
            /**
             * The project's own limits, or `null` when it follows the operator's.
             */
            rate_limit_per_minute: number | null;
            /**
             * Events the quota dropped after ingest had accepted them.
             */
            rate_limited_event_count: number;
            /**
             * The DSN's public key: its 32 hex digits in hyphenated UUID form
             * (8-4-4-4-12), not necessarily an RFC 4122 UUID. The DSN carries the
             * same key without hyphens.
             */
            sentry_key: string;
            slug: string;
            stats?: ProjectListStats | null;
            stored_event_count: number;
            updated_at: string;
        }>;
        page: number;
        per_page: number;
        total_count: number;
        total_pages: number;
    };
};

export type ProjectsListResponse = ProjectsListResponses[keyof ProjectsListResponses];

