export type SpansListData = {
    body?: never;
    path: {
        /**
         * Project ID
         */
        project_id: number;
    };
    query?: {
        /**
         * Page number (1-indexed, default: 1)
         */
        page?: number;
        /**
         * Items per page (default: 20, max: 100)
         */
        per_page?: number;
        /**
         * Filter by span operation, e.g. `http.client`.
         */
        op?: string | null;
        /**
         * Filter by span status.
         */
        status?: string | null;
        /**
         * Filter by trace id — matches spans regardless of origin (standalone
         * or extracted from a transaction), since both share this table.
         */
        trace_id?: string | null;
        /**
         * Filter by gen_ai.operation.type
         * (`agent`/`tool`/`handoff`/`ai_client`/`other`).
         */
        operation_type?: string | null;
    };
    url: '/api/projects/{project_id}/spans';
};

export type SpansListErrors = {
    /**
     * Unauthorized
     */
    401: ErrorResponse;
    /**
     * Not found
     */
    404: ErrorResponse;
};

export type SpansListError = SpansListErrors[keyof SpansListErrors];

export type SpansListResponses = {
    /**
     * Offset-based paginated response wrapper
     */
    200: {
        items: Array<{
            description: string | null;
            /**
             * Duration in milliseconds (timestamp - start_timestamp).
             */
            duration_ms: number | null;
            environment: string | null;
            /**
             * Relay's exclusive (self) time in milliseconds, if provided by the SDK.
             */
            exclusive_time_ms: number | null;
            gen_ai_agent_name: string | null;
            gen_ai_conversation_id: string | null;
            /**
             * gen_ai.* denormalized fields (story-ai-agent-monitoring.md, GH #180).
             * All `None` unless the span was recognized as an AI span.
             */
            gen_ai_operation_type: string | null;
            gen_ai_request_model: string | null;
            gen_ai_response_model: string | null;
            gen_ai_tool_name: string | null;
            gen_ai_usage_input_tokens: number | null;
            gen_ai_usage_output_tokens: number | null;
            gen_ai_usage_total_tokens: number | null;
            id: string;
            is_segment: boolean;
            op: string | null;
            parent_span_id: string | null;
            /**
             * Set for every span. A standalone span reports its own; a
             * transaction-embedded one is stamped with its parent transaction's at
             * write time, rather than being left NULL to be recovered by a JOIN —
             * the agents dashboard filters `spans` directly and a NULL would drop
             * the row from an environment-filtered view.
             */
            platform: string | null;
            release: string | null;
            segment_id: string | null;
            span_id: string | null;
            start_timestamp: string | null;
            status: string | null;
            timestamp: string | null;
            trace_id: string | null;
            /**
             * The parent transaction, if this span was extracted from one.
             * `None` for a standalone span.
             */
            transaction_id: string | null;
        }>;
        page: number;
        per_page: number;
        total_count: number;
        total_pages: number;
    };
};

export type SpansListResponse = SpansListResponses[keyof SpansListResponses];

